-- AI/ML pathway ("Cipher Division") Act 22 -- "Sequence to Sequence" content.
-- Arc IV, World 2 of 5 (world-ai-sequence-to-sequence, act-ai-4). 1 campaign,
-- 2 operations, 12 missions (11 lessons + boss), following the same
-- campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other Act. The worlds/acts/pathways
-- rows already exist (see 20260812130000_ai_acts21_25_world_narrative.sql).

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-sequence-to-sequence', 'world-ai-sequence-to-sequence', 'sequence-to-sequence', '22A - Sequence to Sequence', 'Encoder-decoder models, teacher forcing, the context bottleneck, and the attention mechanism that fixes it -- learning to turn one full stretch of Echo''s output into a clearer generated sequence without silently losing what made it true.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-sequence-to-sequence-1', 'campaign-ai-sequence-to-sequence', 'compress-and-generate', 'Compress and Generate', 'Encoder-decoder basics, autoregressive generation, teacher forcing, the context bottleneck, and the case for attention.', 1),
  ('operation-ai-sequence-to-sequence-2', 'campaign-ai-sequence-to-sequence', 'look-back-to-understand', 'Look Back to Understand', 'Query, key and value, alignment, beam search, evaluation, a full translation run, and the boss case that finds what the first summary lost.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-sequence-to-sequence-01', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-1', 'encoder-decoder', 'Encoder / Decoder', 'Turning Echo''s raw output into something Cipher Division can actually act on means generating new, clearer text from it, not just labeling snippets. The first attempt is a straightforward encoder-decoder summary.', 'beginner', ARRAY['maya','elena'], null, null, '{"type":"simulation","simulationId":"encoder-decoder-sim"}'::jsonb, '{"xp":430,"credits":110}'::jsonb, false, 1),
  ('mission-ai-sequence-to-sequence-02', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-1', 'sequence-generation', 'Sequence Generation', 'A context vector is not a sentence. The decoder has to turn one compressed vector into real words, one token at a time, deciding when enough has been said.', 'beginner', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-sequence-to-sequence-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"sequence-generation-sim"}'::jsonb, '{"xp":440,"credits":110}'::jsonb, false, 2),
  ('mission-ai-sequence-to-sequence-03', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-1', 'teacher-forcing', 'Teacher Forcing', 'The first training runs converge fast and look great -- almost too great. The trick is teacher forcing, and it comes with a catch that only shows up once the model is generating on its own.', 'beginner', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-sequence-to-sequence-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"teacher-forcing-sim"}'::jsonb, '{"xp":440,"credits":115}'::jsonb, false, 3),
  ('mission-ai-sequence-to-sequence-04', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-1', 'context-bottleneck', 'Context Bottleneck', 'Feed the summarizer a short stretch of Echo''s messages and it holds up fine. Feed it a long one, and something starts going missing.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-sequence-to-sequence-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"context-bottleneck-sim"}'::jsonb, '{"xp":450,"credits":115}'::jsonb, false, 4),
  ('mission-ai-sequence-to-sequence-05', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-1', 'why-attention', 'Why Attention?', 'One fixed-size vector cannot hold an unlimited amount of detail. Elena wants the decoder to stop trusting it alone.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-sequence-to-sequence-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"why-attention-sim"}'::jsonb, '{"xp":450,"credits":115}'::jsonb, false, 5),
  ('mission-ai-sequence-to-sequence-06', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-1', 'attention-intuition', 'Attention Intuition', 'Before any formulas, the idea has to make sense in plain terms: let the decoder look back at the whole input, and decide for itself what matters right now.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-sequence-to-sequence-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"attention-intuition-sim"}'::jsonb, '{"xp":460,"credits":120}'::jsonb, false, 6),
  ('mission-ai-sequence-to-sequence-07', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-2', 'query-key-value', 'Query / Key / Value', 'The intuition needs a mechanism: query, key and value turn look-back-and-decide-what-matters into something a model can actually compute.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-sequence-to-sequence-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"query-key-value-sim"}'::jsonb, '{"xp":460,"credits":120}'::jsonb, false, 7),
  ('mission-ai-sequence-to-sequence-08', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-2', 'alignment', 'Alignment', 'Attention weights are not just numbers -- laid out as a grid, they show exactly which input words the decoder leaned on for every output word it wrote.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-sequence-to-sequence-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"alignment-sim"}'::jsonb, '{"xp":470,"credits":120}'::jsonb, false, 8),
  ('mission-ai-sequence-to-sequence-09', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-2', 'beam-search', 'Beam Search', 'Always picking the single most likely next word is not the same as finding the most likely full sentence. Beam search keeps more than one option alive at a time.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-sequence-to-sequence-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"beam-search-sim"}'::jsonb, '{"xp":470,"credits":125}'::jsonb, false, 9),
  ('mission-ai-sequence-to-sequence-10', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-2', 'sequence-evaluation', 'Sequence Evaluation', 'A generated summary needs a score, not just a gut feeling. Automatic metrics compare it to a trusted reference -- and they do not catch everything.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-sequence-to-sequence-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"sequence-evaluation-sim"}'::jsonb, '{"xp":480,"credits":125}'::jsonb, false, 10),
  ('mission-ai-sequence-to-sequence-11', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-2', 'translation-mission', 'Translation Mission', 'Same machinery, harder job: turn a fresh stretch of Echo''s garbled phrasing into something an analyst could actually read, and check the result holds up.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-sequence-to-sequence-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"translation-mission-sim"}'::jsonb, '{"xp":480,"credits":125}'::jsonb, false, 11),
  ('mission-ai-sequence-to-sequence-12', 'world-ai-sequence-to-sequence', 'campaign-ai-sequence-to-sequence', 'operation-ai-sequence-to-sequence-2', 'the-lost-context', 'The Lost Context', 'The team''s first encoder-decoder summary reads clean. The full record says otherwise -- and the gap is not a typo.', 'boss', ARRAY['maya','elena','byte'], '{"requiredMissionIds":["mission-ai-sequence-to-sequence-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-lost-context-boss-sim"}'::jsonb, '{"xp":1100,"credits":240,"badgeIds":["the-lost-context"],"skillXp":{"nlp":55,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-sequence-to-sequence-01', 1, 'maya', 'Vision gave us eyes on Cipher Labs itself. Echo gives us words, and a summary of what it types is not the same as being able to act on it.'),
  ('mission-ai-sequence-to-sequence-01', 2, 'maya', 'Turning Echo''s raw output into something Cipher Division can actually act on means generating new, clearer text from it, not just labeling snippets. The first attempt is a straightforward encoder-decoder summary.'),
  ('mission-ai-sequence-to-sequence-01', 3, 'elena', 'An encoder-decoder model has exactly two halves. The encoder reads the whole input sequence -- every message in the stretch we feed it -- and compresses it down into one fixed-size representation, a context vector.'),
  ('mission-ai-sequence-to-sequence-01', 4, 'elena', 'The decoder never sees the original messages at all. It only sees that one compressed vector, and from it, generates a brand new output sequence, one word at a time, until it decides the summary is done.'),

  ('mission-ai-sequence-to-sequence-02', 1, 'elena', 'The encoder-decoder pipeline is not the whole story yet. Once the decoder has the context vector, it still has to actually build a sentence, and it does that one word at a time.'),
  ('mission-ai-sequence-to-sequence-02', 2, 'elena', 'This is called autoregressive generation. The decoder starts from a special start token, predicts the most likely next word, then treats that predicted word as its own new input for the next step.'),
  ('mission-ai-sequence-to-sequence-02', 3, 'elena', 'It keeps doing that -- predict, feed the prediction back in, predict again -- until it produces a special end token, or hits a length limit we set as a safety net.'),

  ('mission-ai-sequence-to-sequence-03', 1, 'elena', 'Training this decoder from scratch the naive way would be painfully slow -- early on its own predictions are close to garbage, and feeding garbage back in just compounds the error.'),
  ('mission-ai-sequence-to-sequence-03', 2, 'elena', 'So during training we use teacher forcing. At every step, instead of feeding the decoder its own last guess, we feed it the correct previous word straight from the real target summary, no matter what the decoder itself just predicted.'),
  ('mission-ai-sequence-to-sequence-03', 3, 'elena', 'It makes training converge much faster and more stably. The catch is that training and actual use are not quite the same anymore -- at inference time there is no answer key to feed back in, only the model''s own output.'),

  ('mission-ai-sequence-to-sequence-04', 1, 'elena', 'First real test: point the encoder-decoder at a long stretch of Echo''s messages instead of a short one, and see what the summary actually keeps.'),
  ('mission-ai-sequence-to-sequence-04', 2, 'elena', 'Short stretches summarize cleanly. Long ones do not. Details from early in a long input keep disappearing from the output, even when they matter.'),
  ('mission-ai-sequence-to-sequence-04', 3, 'elena', 'The problem is structural, not a training bug. Every input, no matter how long, gets squeezed into the exact same fixed-size context vector. Past a certain length, something has to give.'),

  ('mission-ai-sequence-to-sequence-05', 1, 'elena', 'The fix is not a bigger context vector. Any fixed size eventually runs out for a long enough input -- that just moves the wall further away.'),
  ('mission-ai-sequence-to-sequence-05', 2, 'elena', 'Instead, stop forcing everything through one vector. Let the decoder look directly at every one of the encoder''s states, at every step of generation, and decide for itself what is relevant right now.'),
  ('mission-ai-sequence-to-sequence-05', 3, 'elena', 'That is the entire idea behind attention. It does not replace the encoder-decoder structure -- it removes the one bottleneck sitting in the middle of it.'),

  ('mission-ai-sequence-to-sequence-06', 1, 'elena', 'Before the formulas, get the intuition right. Picture the decoder holding a flashlight over the entire input, and at every single word it generates, it is allowed to move that flashlight.'),
  ('mission-ai-sequence-to-sequence-06', 2, 'byte', 'So it is not reading the input once and forgetting it. At each output step, it re-reads the whole thing and decides what matters for that specific word.'),
  ('mission-ai-sequence-to-sequence-06', 3, 'elena', 'Exactly. Generating the start of a summary might shine the light on the input''s opening lines. Generating the ending might shine it on something from much later. The context used is different every single step.'),

  ('mission-ai-sequence-to-sequence-07', 1, 'elena', 'Time to formalize the flashlight. Attention is usually described with three parts: query, key and value.'),
  ('mission-ai-sequence-to-sequence-07', 2, 'elena', 'The query comes from the decoder -- it represents what the decoder is looking for right now, at this exact generation step. The keys come from the encoder -- one per input position, representing what each position has to offer.'),
  ('mission-ai-sequence-to-sequence-07', 3, 'elena', 'Compare the query against every key to get relevance scores, then use those scores to blend together the values -- which are also drawn from the encoder states. That blend is the step-specific context we talked about.'),

  ('mission-ai-sequence-to-sequence-08', 1, 'elena', 'Every attention score the decoder computes can be laid out as a grid -- one row per output word, one column per input word. That grid is called an alignment.'),
  ('mission-ai-sequence-to-sequence-08', 2, 'elena', 'A healthy alignment usually looks sharp: each output word leans heavily on a small, sensible cluster of input words. When the grid comes out smeared across everything with no clear focus, that step''s word choice is worth double-checking.'),

  ('mission-ai-sequence-to-sequence-09', 1, 'elena', 'One more decision point. When the decoder predicts the next word, always taking the single most likely one -- greedy decoding -- is fast, but it can lock in an early choice that ruins the whole sentence later.'),
  ('mission-ai-sequence-to-sequence-09', 2, 'byte', 'Beam search hedges against that. Instead of keeping only the single best partial sequence at each step, it keeps the top few, expands all of them, and only prunes back down to the top few again.'),
  ('mission-ai-sequence-to-sequence-09', 3, 'elena', 'It costs more compute for a better shot at the highest-scoring full sequence overall, not just the highest-scoring next word. For a summary Cipher Division might act on, that trade is usually worth it.'),

  ('mission-ai-sequence-to-sequence-10', 1, 'elena', 'Once a summary comes out, Cipher Division needs a number, not just a feeling about whether it reads well. The standard approach compares the generated summary against a trusted reference summary and scores the overlap.'),
  ('mission-ai-sequence-to-sequence-10', 2, 'elena', 'That overlap score is useful, but it is not the whole picture. It measures matching words and phrases -- it has no way to check whether a specific fact or detail in the summary is actually correct.'),

  ('mission-ai-sequence-to-sequence-11', 1, 'elena', 'Full toolkit assembled: encoder-decoder, attention, beam search, a way to evaluate the result. Time to actually use it on new material.'),
  ('mission-ai-sequence-to-sequence-11', 2, 'elena', 'Echo''s raw phrasing is close enough to a foreign language that the same machinery applies directly. Feed in a fresh, garbled stretch of Echo''s output, and treat generating a clear English explanation of it as a translation problem, not a special case.'),
  ('mission-ai-sequence-to-sequence-11', 3, 'elena', 'Run it, then check the result the same way we would check any generated text: does it actually preserve what the source said, or does it just sound fluent?'),

  ('mission-ai-sequence-to-sequence-12', 1, 'maya', 'The first full-length encoder-decoder summary of Echo''s messages is done. Before Cipher Division acts on a single line of it, I want it checked against the actual record, not just read and trusted.'),
  ('mission-ai-sequence-to-sequence-12', 2, 'byte', 'I pulled the summary and the full raw log side by side. Three things need your judgment before we move on this.'),
  ('mission-ai-sequence-to-sequence-12', 3, 'elena', 'Start with the summary itself. It describes one of Echo''s recurring questions as something that showed up recently. Compare that claim against what the full log actually shows.'),
  ('mission-ai-sequence-to-sequence-12', 4, 'elena', 'Once you know whether the claim holds up, work out why -- if it does not, the model did not just make a small mistake. Something about how it was built would have to be the reason.'),
  ('mission-ai-sequence-to-sequence-12', 5, 'elena', 'And if that reason is what we think it is, there is one more thing to check: does fixing it actually recover the truth, or just a different guess?'),
  ('mission-ai-sequence-to-sequence-12', 6, 'maya', 'One summary, done right, is not the same as knowing what these words actually mean to a system that has no dictionary of its own. Meaning is the next problem, not just better sentences.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-sequence-to-sequence-01-o1', 'mission-ai-sequence-to-sequence-01', 1, 'Locate the handoff', 'Identify what the encoder actually hands off to the decoder.'),
  ('mission-ai-sequence-to-sequence-01-o2', 'mission-ai-sequence-to-sequence-01', 2, 'Order the pipeline', 'Put the stages of an encoder-decoder run in the order they actually happen.'),

  ('mission-ai-sequence-to-sequence-02-o1', 'mission-ai-sequence-to-sequence-02', 1, 'Define the loop', 'State what makes decoder generation autoregressive.'),
  ('mission-ai-sequence-to-sequence-02-o2', 'mission-ai-sequence-to-sequence-02', 2, 'Order one generation step', 'Put the stages of a single decoding step in order.'),

  ('mission-ai-sequence-to-sequence-03-o1', 'mission-ai-sequence-to-sequence-03', 1, 'Define teacher forcing', 'State what actually happens to the decoder input during training.'),
  ('mission-ai-sequence-to-sequence-03-o2', 'mission-ai-sequence-to-sequence-03', 2, 'Trace the mismatch', 'Find the evidence that explains why an early inference summary can drift off track after one wrong word.'),

  ('mission-ai-sequence-to-sequence-04-o1', 'mission-ai-sequence-to-sequence-04', 1, 'Name the problem', 'Identify the technical name for a fixed-size vector failing to hold a long input.'),
  ('mission-ai-sequence-to-sequence-04-o2', 'mission-ai-sequence-to-sequence-04', 2, 'Find the evidence', 'Confirm the bottleneck shows up in the benchmark data, not just as a guess.'),

  ('mission-ai-sequence-to-sequence-05-o1', 'mission-ai-sequence-to-sequence-05', 1, 'State the fix', 'Identify what attention actually gives the decoder access to.'),
  ('mission-ai-sequence-to-sequence-05-o2', 'mission-ai-sequence-to-sequence-05', 2, 'Sort before and after', 'Sort each statement into how a model behaves before attention or with attention.'),

  ('mission-ai-sequence-to-sequence-06-o1', 'mission-ai-sequence-to-sequence-06', 1, 'Pin the intuition', 'Choose the description that matches what attention actually does at each step.'),
  ('mission-ai-sequence-to-sequence-06-o2', 'mission-ai-sequence-to-sequence-06', 2, 'Order the intuition', 'Put the intuitive steps of one attention-assisted decoding step in order.'),

  ('mission-ai-sequence-to-sequence-07-o1', 'mission-ai-sequence-to-sequence-07', 1, 'Locate the query', 'Identify where the query comes from and what it represents.'),
  ('mission-ai-sequence-to-sequence-07-o2', 'mission-ai-sequence-to-sequence-07', 2, 'Match the roles', 'Match each term to its actual role in attention.'),

  ('mission-ai-sequence-to-sequence-08-o1', 'mission-ai-sequence-to-sequence-08', 1, 'Define alignment', 'State what an alignment matrix actually represents.'),
  ('mission-ai-sequence-to-sequence-08-o2', 'mission-ai-sequence-to-sequence-08', 2, 'Judge the alignments', 'Find the alignment evidence that signals a healthy, focused attention pattern.'),

  ('mission-ai-sequence-to-sequence-09-o1', 'mission-ai-sequence-to-sequence-09', 1, 'State the trade', 'Identify the core tradeoff of beam search compared to greedy decoding.'),
  ('mission-ai-sequence-to-sequence-09-o2', 'mission-ai-sequence-to-sequence-09', 2, 'Order a beam search run', 'Put the stages of a beam search run in order.'),

  ('mission-ai-sequence-to-sequence-10-o1', 'mission-ai-sequence-to-sequence-10', 1, 'Define the metric', 'State what an overlap-based metric like the ones used here actually measures.'),
  ('mission-ai-sequence-to-sequence-10-o2', 'mission-ai-sequence-to-sequence-10', 2, 'Find the limitation', 'Find the evidence that shows the real limitation of relying on overlap scores alone.'),

  ('mission-ai-sequence-to-sequence-11-o1', 'mission-ai-sequence-to-sequence-11', 1, 'Justify the framing', 'State why this task counts as translation in the technical sense.'),
  ('mission-ai-sequence-to-sequence-11-o2', 'mission-ai-sequence-to-sequence-11', 2, 'Judge the output', 'Compare two candidate translations of a garbled Echo excerpt against the source and pick the more faithful one.'),

  ('mission-ai-sequence-to-sequence-12-o1', 'mission-ai-sequence-to-sequence-12', 1, 'Compare summary to record', 'Check the encoder-decoder summary claim about when a recurring question first appeared against the full raw log.'),
  ('mission-ai-sequence-to-sequence-12-o2', 'mission-ai-sequence-to-sequence-12', 2, 'Diagnose the bottleneck', 'Identify the technical reason the fixed-size context vector caused this specific detail to go missing.'),
  ('mission-ai-sequence-to-sequence-12-o3', 'mission-ai-sequence-to-sequence-12', 3, 'Confirm the fix', 'Check whether an attention-based re-run actually recovers the correct timeline, not just a different answer.'),
  ('mission-ai-sequence-to-sequence-12-o4', 'mission-ai-sequence-to-sequence-12', 4, 'Close the case', 'Having judged all three, state what this means for how Cipher Division treats any single generated summary going forward.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-sequence-to-sequence-01-o1-c1', 'mission-ai-sequence-to-sequence-01-o1', 1, 'multiple_choice', 'In an encoder-decoder model, what does the encoder actually produce for the decoder to use?', '{"question":"In an encoder-decoder model, what does the encoder actually produce for the decoder to use?","options":[{"id":"a","text":"The original input sequence, unchanged"},{"id":"b","text":"A single fixed-size vector summarizing the whole input sequence"},{"id":"c","text":"A list of grammar rules extracted from the input"},{"id":"d","text":"A copy of the decoder''s own weights"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-sequence-to-sequence-01-o2-c1', 'mission-ai-sequence-to-sequence-01-o2', 1, 'interactive_diagram', 'Order the stages of a single encoder-decoder run from first to last.', '{"diagramId":"encoder-decoder-pipeline","hotspots":[{"id":"h1","label":"Encoder reads the input sequence, one token at a time","explanation":"Every token in Echo''s message stretch is processed in order, building up the encoder''s internal state."},{"id":"h2","label":"Encoder''s final state becomes the fixed-size context vector","explanation":"Once the whole input has been read, whatever the encoder is holding gets treated as its complete summary of that input."},{"id":"h3","label":"Decoder is initialized from that context vector","explanation":"The decoder starts generating with no access to the original text -- only to what the encoder compressed it into."},{"id":"h4","label":"Decoder generates the output sequence, one token at a time","explanation":"Each new output token gets fed back in as the decoder continues, until it produces an end-of-sequence signal."}],"task":"Order the stages of a single encoder-decoder run from first to last."}'::jsonb, '{"correctOrderIds":["h1","h2","h3","h4"]}'::jsonb),

  ('mission-ai-sequence-to-sequence-02-o1-c1', 'mission-ai-sequence-to-sequence-02-o1', 1, 'multiple_choice', 'Why is decoder generation in a sequence-to-sequence model described as autoregressive?', '{"question":"Why is decoder generation in a sequence-to-sequence model described as autoregressive?","options":[{"id":"a","text":"Because it only works on numerical data"},{"id":"b","text":"Because each generated token is fed back in as input for generating the next token"},{"id":"c","text":"Because the encoder and decoder share the exact same weights"},{"id":"d","text":"Because it always generates exactly the same length output as the input"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-sequence-to-sequence-02-o2-c1', 'mission-ai-sequence-to-sequence-02-o2', 1, 'interactive_diagram', 'Order the stages of a single decoding step, from receiving input to producing the next token.', '{"diagramId":"decoder-generation-step","hotspots":[{"id":"h1","label":"Decoder takes the previous token as its current input","explanation":"On the very first step this is the special start token; after that, it is whatever the decoder just generated."},{"id":"h2","label":"Decoder combines that input with its internal state","explanation":"The internal state carries forward everything generated so far in this output sequence."},{"id":"h3","label":"Decoder outputs a probability distribution over the vocabulary","explanation":"Every possible next word gets a probability; the most likely one is typically chosen."},{"id":"h4","label":"The chosen token is emitted and fed back in as the next input","explanation":"That feedback loop is what makes the process autoregressive, and it repeats until an end token is produced."}],"task":"Order the stages of a single decoding step, from receiving input to producing the next token."}'::jsonb, '{"correctOrderIds":["h1","h2","h3","h4"]}'::jsonb),

  ('mission-ai-sequence-to-sequence-03-o1-c1', 'mission-ai-sequence-to-sequence-03-o1', 1, 'multiple_choice', 'During training with teacher forcing, what does the decoder receive as input at each step?', '{"question":"During training with teacher forcing, what does the decoder receive as input at each step?","options":[{"id":"a","text":"The decoder''s own prediction from the previous step"},{"id":"b","text":"The correct previous token from the real target sequence, regardless of what the decoder predicted"},{"id":"c","text":"A random token from the vocabulary"},{"id":"d","text":"The entire target sequence at once"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-sequence-to-sequence-03-o2-c1', 'mission-ai-sequence-to-sequence-03-o2', 1, 'investigation', 'Which evidence explains why an early inference summary can drift further off track after a single wrong word, even though training looked stable?', '{"evidence":[{"id":"e1","label":"Training log","detail":"At every training step, the decoder''s input was the correct previous word taken directly from the target summary in the dataset, never the decoder''s own prior guess."},{"id":"e2","label":"Architecture note","detail":"The encoder and decoder are separate networks and do not share any weights."},{"id":"e3","label":"Hardware note","detail":"Training ran across a cluster of identical GPU nodes."}],"question":"Which evidence explains why an early inference summary can drift further off track after a single wrong word, even though training looked stable?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-sequence-to-sequence-04-o1-c1', 'mission-ai-sequence-to-sequence-04-o1', 1, 'multiple_choice', 'What is the context bottleneck in a basic encoder-decoder model?', '{"question":"What is the context bottleneck in a basic encoder-decoder model?","options":[{"id":"a","text":"The decoder generating too slowly"},{"id":"b","text":"The fixed-size context vector losing information because it must represent an entire input sequence regardless of length"},{"id":"c","text":"A limit on how many training examples the model can see"},{"id":"d","text":"The encoder and decoder disagreeing on vocabulary size"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-sequence-to-sequence-04-o2-c1', 'mission-ai-sequence-to-sequence-04-o2', 1, 'investigation', 'Which evidence points specifically to the fixed-size context vector as the cause of dropped detail?', '{"evidence":[{"id":"e1","label":"Benchmark note","detail":"On inputs under 20 tokens, summary accuracy holds steady around 95 percent."},{"id":"e2","label":"Benchmark note","detail":"On inputs over 200 tokens, summary accuracy drops to 61 percent, with details from early in the input the most frequently missing."},{"id":"e3","label":"Ops note","detail":"Response time per summary stays roughly constant no matter the input length."}],"question":"Which evidence points specifically to the fixed-size context vector as the cause of dropped detail?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-sequence-to-sequence-05-o1-c1', 'mission-ai-sequence-to-sequence-05-o1', 1, 'multiple_choice', 'What problem does attention directly solve, compared to a basic encoder-decoder model?', '{"question":"What problem does attention directly solve, compared to a basic encoder-decoder model?","options":[{"id":"a","text":"It removes the need for a decoder entirely"},{"id":"b","text":"It lets the decoder access all of the encoder''s states directly, instead of relying on one fixed-size summary vector"},{"id":"c","text":"It makes the vocabulary smaller"},{"id":"d","text":"It removes the need for training data"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-sequence-to-sequence-05-o2-c1', 'mission-ai-sequence-to-sequence-05-o2', 1, 'drag_and_drop', 'Sort each statement into how a model behaves before attention or with attention.', '{"items":[{"id":"i1","text":"The decoder only ever sees one fixed-size vector, no matter the input length"},{"id":"i2","text":"The decoder can weigh every encoder state differently at each generation step"},{"id":"i3","text":"Long inputs reliably lose early detail"},{"id":"i4","text":"Relevant information can be pulled from anywhere in the input, regardless of length"}],"targets":[{"id":"t1","label":"Before attention"},{"id":"t2","label":"With attention"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-ai-sequence-to-sequence-06-o1-c1', 'mission-ai-sequence-to-sequence-06-o1', 1, 'multiple_choice', 'In plain terms, what does attention let the decoder do at each generation step?', '{"question":"In plain terms, what does attention let the decoder do at each generation step?","options":[{"id":"a","text":"Re-read the entire input and dynamically decide which parts matter most for the word it is generating right now"},{"id":"b","text":"Ignore the input entirely and rely only on its own prior outputs"},{"id":"c","text":"Permanently fix which input words matter, before generation even starts"},{"id":"d","text":"Generate the whole output sequence in a single step"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-sequence-to-sequence-06-o2-c1', 'mission-ai-sequence-to-sequence-06-o2', 1, 'interactive_diagram', 'Order the intuitive steps of attention-assisted decoding, from reaching a generation step to using a step-specific context.', '{"diagramId":"attention-intuition-flow","hotspots":[{"id":"h1","label":"Decoder reaches a point where it needs to generate the next word","explanation":"Generation is still one word at a time, exactly as before attention was added."},{"id":"h2","label":"Decoder looks back across the entire input, not just the final compressed vector","explanation":"Every encoder state from every input position is available to consider, not only the last one."},{"id":"h3","label":"Decoder judges how relevant each input position is to the word it is about to generate","explanation":"Relevance is not fixed -- it is recomputed fresh for every single output word."},{"id":"h4","label":"The most relevant parts are blended together into a step-specific context used for that one word","explanation":"This step-specific context replaces the single, one-size-fits-all vector from the basic encoder-decoder model."}],"task":"Order the intuitive steps of attention-assisted decoding, from reaching a generation step to using a step-specific context."}'::jsonb, '{"correctOrderIds":["h1","h2","h3","h4"]}'::jsonb),

  ('mission-ai-sequence-to-sequence-07-o1-c1', 'mission-ai-sequence-to-sequence-07-o1', 1, 'multiple_choice', 'In the query/key/value framing of attention, what does the query represent?', '{"question":"In the query/key/value framing of attention, what does the query represent?","options":[{"id":"a","text":"What each encoder position has to offer, fixed in advance"},{"id":"b","text":"What the decoder is currently looking for at this generation step"},{"id":"c","text":"The final output token, already chosen"},{"id":"d","text":"The size of the vocabulary"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-sequence-to-sequence-07-o2-c1', 'mission-ai-sequence-to-sequence-07-o2', 1, 'drag_and_drop', 'Match each term to its actual role in attention.', '{"items":[{"id":"i1","text":"Query"},{"id":"i2","text":"Key"},{"id":"i3","text":"Value"}],"targets":[{"id":"t1","label":"What the decoder is currently looking for"},{"id":"t2","label":"What each encoder position offers to be matched against"},{"id":"t3","label":"What actually gets blended together once relevance is decided"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),

  ('mission-ai-sequence-to-sequence-08-o1-c1', 'mission-ai-sequence-to-sequence-08-o1', 1, 'multiple_choice', 'What does an attention alignment matrix show?', '{"question":"What does an attention alignment matrix show?","options":[{"id":"a","text":"The order in which training examples were seen"},{"id":"b","text":"How much weight each output word placed on each input word when it was generated"},{"id":"c","text":"The vocabulary size of the model"},{"id":"d","text":"How many layers the encoder has"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-sequence-to-sequence-08-o2-c1', 'mission-ai-sequence-to-sequence-08-o2', 1, 'investigation', 'Which alignment evidence shows a healthy, focused attention pattern rather than a diffuse, unreliable one?', '{"evidence":[{"id":"e1","label":"Alignment grid A","detail":"The output word unauthorized places over 80 percent of its attention weight on the two input tokens not and authorized."},{"id":"e2","label":"Alignment grid B","detail":"The output word unauthorized spreads its attention weight almost evenly across all forty input tokens, with no position standing out."},{"id":"e3","label":"Alignment grid C","detail":"The alignment grid was generated using the same color scale for every row."}],"question":"Which alignment evidence shows a healthy, focused attention pattern rather than a diffuse, unreliable one?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-sequence-to-sequence-09-o1-c1', 'mission-ai-sequence-to-sequence-09-o1', 1, 'multiple_choice', 'What is the main tradeoff beam search makes compared to greedy decoding?', '{"question":"What is the main tradeoff beam search makes compared to greedy decoding?","options":[{"id":"a","text":"It uses less compute to produce a strictly worse sequence"},{"id":"b","text":"It uses more compute to keep multiple candidate sequences alive, improving the odds of finding a better full sequence overall"},{"id":"c","text":"It removes the need for a decoder"},{"id":"d","text":"It guarantees a perfect output every time"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-sequence-to-sequence-09-o2-c1', 'mission-ai-sequence-to-sequence-09-o2', 1, 'interactive_diagram', 'Order the stages of a beam search run, from the initial candidate to the final chosen sequence.', '{"diagramId":"beam-search-flow","hotspots":[{"id":"h1","label":"Start with the start token as the single initial candidate sequence","explanation":"Beam search begins the same way greedy decoding does, with one starting point."},{"id":"h2","label":"Expand every current candidate by every possible next token","explanation":"Each candidate branches out, generating many more partial sequences than before."},{"id":"h3","label":"Score every resulting candidate sequence","explanation":"Scores are typically based on the combined probability of the sequence so far."},{"id":"h4","label":"Keep only the top-scoring candidates, up to the beam width","explanation":"Lower-scoring candidates get discarded here, keeping the search from exploding in size."},{"id":"h5","label":"Repeat expansion and pruning until candidates end or hit a length limit","explanation":"This loop continues, one generation step at a time, for every surviving candidate."},{"id":"h6","label":"Return the highest-scoring completed candidate sequence","explanation":"Once candidates finish, the single best full sequence is the beam search output."}],"task":"Order the stages of a beam search run, from the initial candidate to the final chosen sequence."}'::jsonb, '{"correctOrderIds":["h1","h2","h3","h4","h5","h6"]}'::jsonb),

  ('mission-ai-sequence-to-sequence-10-o1-c1', 'mission-ai-sequence-to-sequence-10-o1', 1, 'multiple_choice', 'What does an automatic overlap-based evaluation metric for generated text actually measure?', '{"question":"What does an automatic overlap-based evaluation metric for generated text actually measure?","options":[{"id":"a","text":"Whether every fact in the summary is verified as true"},{"id":"b","text":"How much the generated text''s words and phrases overlap with a trusted reference text"},{"id":"c","text":"How fast the model generated the summary"},{"id":"d","text":"How many parameters the model has"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-sequence-to-sequence-10-o2-c1', 'mission-ai-sequence-to-sequence-10-o2', 1, 'investigation', 'Which evidence shows the real limitation of relying on overlap-based metrics alone?', '{"evidence":[{"id":"e1","label":"Metric report","detail":"A generated summary scores 0.88 overlap against the reference summary."},{"id":"e2","label":"Manual review note","detail":"A reviewer flags that a specific timestamp claim in the generated summary does not match the source log, despite the summary''s high overlap score."},{"id":"e3","label":"Metric report","detail":"Overlap scores are computed automatically in under a second per summary."}],"question":"Which evidence shows the real limitation of relying on overlap-based metrics alone?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-sequence-to-sequence-11-o1-c1', 'mission-ai-sequence-to-sequence-11-o1', 1, 'multiple_choice', 'Why can turning Echo''s garbled output into clear English be treated as a translation problem?', '{"question":"Why can turning Echo''s garbled output into clear English be treated as a translation problem?","options":[{"id":"a","text":"Because Echo''s output is written in a different human language"},{"id":"b","text":"Because it is still a sequence-in, sequence-out task -- the same encoder-decoder-with-attention machinery applies regardless of what the two sequences are"},{"id":"c","text":"Because translation models cannot generate summaries"},{"id":"d","text":"Because beam search only works on foreign languages"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-sequence-to-sequence-11-o2-c1', 'mission-ai-sequence-to-sequence-11-o2', 1, 'investigation', 'Given the source excerpt, which candidate translation is actually the more faithful one, even though it reads less smoothly?', '{"evidence":[{"id":"e1","label":"Source excerpt","detail":"Echo''s raw log line reads, in part, a garbled fragment about a containment check repeating without resolution."},{"id":"e2","label":"Candidate A","detail":"Fluent, confident English sentence that describes a single containment check completing successfully."},{"id":"e3","label":"Candidate B","detail":"Slightly less polished English sentence that describes a containment check repeating without ever resolving, matching the source excerpt."}],"question":"Given the source excerpt, which candidate translation is actually the more faithful one, even though it reads less smoothly?"}'::jsonb, '{"requiredEvidenceIds":["e3"]}'::jsonb),

  ('mission-ai-sequence-to-sequence-12-o1-c1', 'mission-ai-sequence-to-sequence-12-o1', 1, 'investigation', 'Compare the summary claim about when the recurring question first appeared against the full raw log. What does the record actually show?', '{"evidence":[{"id":"e1","label":"Encoder-decoder summary","detail":"States that one of Echo''s recurring questions first appears roughly two-thirds of the way through the reviewed stretch of messages."},{"id":"e2","label":"Full raw log, early segment","detail":"The same recurring question pattern is already present in messages from near the very start of the reviewed stretch, far earlier than the summary suggests."},{"id":"e3","label":"Full raw log, metadata","detail":"Timestamps confirm the early-segment messages predate the point the summary treats as the pattern''s first appearance by a wide margin."}],"question":"Compare the summary claim about when the recurring question first appeared against the full raw log. What does the record actually show?"}'::jsonb, '{"requiredEvidenceIds":["e2","e3"]}'::jsonb),
  ('mission-ai-sequence-to-sequence-12-o2-c1', 'mission-ai-sequence-to-sequence-12-o2', 1, 'multiple_choice', 'What technical property of the first, attention-free encoder-decoder model explains why its summary lost exactly when the recurring question first appeared?', '{"question":"What technical property of the first, attention-free encoder-decoder model explains why its summary lost exactly when the recurring question first appeared?","options":[{"id":"a","text":"The model used the wrong tokenizer for Echo''s vocabulary"},{"id":"b","text":"The fixed-size context bottleneck compressed the entire long stretch into one vector, and early detail from a long sequence is exactly what that bottleneck tends to drop"},{"id":"c","text":"The training data had incorrect labels"},{"id":"d","text":"The hardware ran out of memory partway through"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-sequence-to-sequence-12-o3-c1', 'mission-ai-sequence-to-sequence-12-o3', 1, 'investigation', 'Does the attention-based re-run actually recover the correct timeline, or just produce a different guess?', '{"evidence":[{"id":"e1","label":"Attention-based re-run summary","detail":"States that the recurring question pattern is present from near the very start of the reviewed stretch, consistent with the full raw log."},{"id":"e2","label":"Comparison note","detail":"The attention-based re-run stated first-appearance point matches the timestamp confirmed directly against the full raw log, unlike the original summary."},{"id":"e3","label":"Compute note","detail":"The attention-based re-run took longer to generate than the original summary."}],"question":"Does the attention-based re-run actually recover the correct timeline, or just produce a different guess?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-sequence-to-sequence-12-o4-c1', 'mission-ai-sequence-to-sequence-12-o4', 1, 'boss_encounter', 'Having compared the summary to the record, diagnosed why the detail was lost, and confirmed the fix recovers the truth, state what this means for how Cipher Division treats any single generated summary going forward.', '{"stages":[{"objectiveRef":"mission-ai-sequence-to-sequence-12-o1","label":"Compare summary to record"},{"objectiveRef":"mission-ai-sequence-to-sequence-12-o2","label":"Diagnose the bottleneck"},{"objectiveRef":"mission-ai-sequence-to-sequence-12-o3","label":"Confirm the fix"}],"task":"State the lesson in one sentence: a generated summary is a claim that has to be checked against the underlying record, not a certainty, especially one built without attention."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-sequence-to-sequence-12-o1","mission-ai-sequence-to-sequence-12-o2","mission-ai-sequence-to-sequence-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-sequence-to-sequence-01-o1-c1', 'orientation', 'Think about what actually crosses the boundary between encoder and decoder -- it is not the raw text.', 10, 1),
  ('mission-ai-sequence-to-sequence-01-o1-c1', 'concept', 'The decoder in a basic encoder-decoder model never reads the original input sequence directly.', 20, 2),
  ('mission-ai-sequence-to-sequence-01-o1-c1', 'solution', 'b: a single fixed-size vector, the context vector, summarizing the whole input -- that is all the decoder gets.', 30, 3),
  ('mission-ai-sequence-to-sequence-01-o2-c1', 'orientation', 'Nothing can be summarized before it has all been read.', 10, 1),
  ('mission-ai-sequence-to-sequence-01-o2-c1', 'concept', 'The decoder cannot start until there is a context vector for it to start from.', 20, 2),
  ('mission-ai-sequence-to-sequence-01-o2-c1', 'solution', 'Read the input, build the context vector, initialize the decoder, generate output tokens one at a time.', 30, 3),

  ('mission-ai-sequence-to-sequence-02-o1-c1', 'orientation', 'Focus on what the decoder does with the word it just generated.', 10, 1),
  ('mission-ai-sequence-to-sequence-02-o1-c1', 'concept', 'A model is autoregressive when each output depends on the outputs it already produced.', 20, 2),
  ('mission-ai-sequence-to-sequence-02-o1-c1', 'solution', 'b: each generated token becomes the next input, so every prediction depends on everything generated before it.', 30, 3),
  ('mission-ai-sequence-to-sequence-02-o2-c1', 'orientation', 'Nothing can be emitted before the decoder has combined an input with its running state.', 10, 1),
  ('mission-ai-sequence-to-sequence-02-o2-c1', 'concept', 'A probability distribution has to exist before any specific token can be chosen from it.', 20, 2),
  ('mission-ai-sequence-to-sequence-02-o2-c1', 'solution', 'Take the previous token as input, combine it with the internal state, produce a probability distribution, emit the chosen token and feed it back.', 30, 3),

  ('mission-ai-sequence-to-sequence-03-o1-c1', 'orientation', 'Ask whose word choice actually lands in the decoder input slot during training.', 10, 1),
  ('mission-ai-sequence-to-sequence-03-o1-c1', 'solution', 'b: the real target word gets fed in every time, regardless of what the decoder itself predicted.', 20, 2),
  ('mission-ai-sequence-to-sequence-03-o2-c1', 'orientation', 'During training, the decoder never has to rely on its own guesses to keep going -- something else supplies the correct input.', 10, 1),
  ('mission-ai-sequence-to-sequence-03-o2-c1', 'concept', 'That safety net disappears completely at inference time, when the model must feed back its own generated words instead.', 20, 2),
  ('mission-ai-sequence-to-sequence-03-o2-c1', 'solution', 'e1: because training always supplied the true previous word, the decoder never practiced recovering from its own mistakes, so a wrong word during inference has nothing to correct it, only more of the model''s own drifting output.', 30, 3),

  ('mission-ai-sequence-to-sequence-04-o1-c1', 'orientation', 'Every input, short or long, gets compressed into the same size vector.', 10, 1),
  ('mission-ai-sequence-to-sequence-04-o1-c1', 'concept', 'There is only so much a fixed number of dimensions can represent before something must be approximated away.', 20, 2),
  ('mission-ai-sequence-to-sequence-04-o1-c1', 'solution', 'b: the fixed-size context vector cannot scale with input length, so long sequences lose information -- that is the context bottleneck.', 30, 3),
  ('mission-ai-sequence-to-sequence-04-o2-c1', 'orientation', 'Response time does not tell you anything about what got lost.', 10, 1),
  ('mission-ai-sequence-to-sequence-04-o2-c1', 'solution', 'e2: accuracy collapsing specifically on long inputs, and specifically losing early details, is the signature of the fixed-size vector running out of room.', 20, 2),

  ('mission-ai-sequence-to-sequence-05-o1-c1', 'orientation', 'Attention does not shrink the input -- it changes what the decoder is allowed to look at.', 10, 1),
  ('mission-ai-sequence-to-sequence-05-o1-c1', 'solution', 'b: attention gives the decoder direct access to every encoder state, not just one compressed summary of all of them.', 20, 2),
  ('mission-ai-sequence-to-sequence-05-o2-c1', 'orientation', 'Ask which behavior depends on squeezing everything into one vector first.', 10, 1),
  ('mission-ai-sequence-to-sequence-05-o2-c1', 'solution', 'Before attention: one fixed vector only, long inputs losing detail. With attention: weighing every state per step, pulling relevant information from anywhere in the input.', 20, 2),

  ('mission-ai-sequence-to-sequence-06-o1-c1', 'orientation', 'The key word is dynamically -- this happens fresh at every step, not once.', 10, 1),
  ('mission-ai-sequence-to-sequence-06-o1-c1', 'solution', 'a: attention re-reads the whole input at every step and decides what matters for that specific word being generated.', 20, 2),
  ('mission-ai-sequence-to-sequence-06-o2-c1', 'orientation', 'The decoder still needs a reason to generate before it can look back at anything.', 10, 1),
  ('mission-ai-sequence-to-sequence-06-o2-c1', 'concept', 'Relevance has to be judged before it can be blended into a usable context.', 20, 2),
  ('mission-ai-sequence-to-sequence-06-o2-c1', 'solution', 'Reach a generation step, look back across the whole input, judge relevance of each position, then blend the relevant parts into a step-specific context.', 30, 3),

  ('mission-ai-sequence-to-sequence-07-o1-c1', 'orientation', 'The query is generated fresh, from the decoder current step -- not fixed in advance.', 10, 1),
  ('mission-ai-sequence-to-sequence-07-o1-c1', 'solution', 'b: the query represents what the decoder needs right now, to generate the current output token.', 20, 2),
  ('mission-ai-sequence-to-sequence-07-o2-c1', 'orientation', 'Ask three separate questions: what is being searched for, what is being searched against, and what is actually collected.', 10, 1),
  ('mission-ai-sequence-to-sequence-07-o2-c1', 'concept', 'Keys and values both come from the encoder, but they play different roles -- keys are compared against, values get blended.', 20, 2),
  ('mission-ai-sequence-to-sequence-07-o2-c1', 'solution', 'Query: what the decoder is looking for. Key: what each encoder position offers to be matched against. Value: what gets blended together once relevance is decided.', 30, 3),

  ('mission-ai-sequence-to-sequence-08-o1-c1', 'orientation', 'Think rows and columns -- one axis is output words, the other is input words.', 10, 1),
  ('mission-ai-sequence-to-sequence-08-o1-c1', 'solution', 'b: an alignment matrix shows the attention weight between every output word and every input word.', 20, 2),
  ('mission-ai-sequence-to-sequence-08-o2-c1', 'orientation', 'A focused alignment concentrates weight on a small, relevant set of input words.', 10, 1),
  ('mission-ai-sequence-to-sequence-08-o2-c1', 'solution', 'e1: heavy weight concentrated on the two directly relevant input tokens is exactly what a healthy, focused alignment looks like -- the even spread in e2 is the warning sign.', 20, 2),

  ('mission-ai-sequence-to-sequence-09-o1-c1', 'orientation', 'Greedy decoding never reconsiders an early choice once it is made.', 10, 1),
  ('mission-ai-sequence-to-sequence-09-o1-c1', 'concept', 'Beam search''s advantage comes specifically from keeping more than one option alive at once.', 20, 2),
  ('mission-ai-sequence-to-sequence-09-o1-c1', 'solution', 'b: beam search trades extra compute for keeping several candidate sequences alive, improving the chance of finding the best full sequence rather than just the best next word.', 30, 3),
  ('mission-ai-sequence-to-sequence-09-o2-c1', 'orientation', 'Nothing can be scored before it has been expanded into candidates first.', 10, 1),
  ('mission-ai-sequence-to-sequence-09-o2-c1', 'concept', 'Pruning back down to the beam width has to happen after scoring, not before.', 20, 2),
  ('mission-ai-sequence-to-sequence-09-o2-c1', 'solution', 'Start with the initial candidate, expand every candidate by every possible next token, score every resulting candidate, keep only the top-scoring ones, repeat until finished, then return the highest-scoring completed sequence.', 30, 3),

  ('mission-ai-sequence-to-sequence-10-o1-c1', 'orientation', 'The metric compares text to text, not claims to reality.', 10, 1),
  ('mission-ai-sequence-to-sequence-10-o1-c1', 'solution', 'b: overlap-based metrics measure how much the generated words and phrases match a reference -- nothing more.', 20, 2),
  ('mission-ai-sequence-to-sequence-10-o2-c1', 'orientation', 'A high score and a wrong detail can both be true about the same summary.', 10, 1),
  ('mission-ai-sequence-to-sequence-10-o2-c1', 'solution', 'e2: a summary can score high on word overlap while still containing a factual mismatch the metric has no way to catch -- that is the real limitation.', 20, 2),

  ('mission-ai-sequence-to-sequence-11-o1-c1', 'orientation', 'Ignore what the two sequences represent in the story -- focus on the shape of the task.', 10, 1),
  ('mission-ai-sequence-to-sequence-11-o1-c1', 'solution', 'b: translation, summarization and this task are all sequence-to-sequence problems -- the same architecture applies regardless of the content.', 20, 2),
  ('mission-ai-sequence-to-sequence-11-o2-c1', 'orientation', 'Fluency and faithfulness are not the same thing -- a smooth sentence can still be wrong.', 10, 1),
  ('mission-ai-sequence-to-sequence-11-o2-c1', 'concept', 'Compare each candidate against the source excerpt actual content, not against how natural each candidate sounds.', 20, 2),
  ('mission-ai-sequence-to-sequence-11-o2-c1', 'solution', 'e3, Candidate B: it is less polished but actually matches what the source excerpt describes -- Candidate A reads better but contradicts the source.', 30, 3),

  ('mission-ai-sequence-to-sequence-12-o1-c1', 'orientation', 'Do not just read the summary claim -- check it against the same stretch of the actual raw log.', 10, 1),
  ('mission-ai-sequence-to-sequence-12-o1-c1', 'concept', 'A recurring pattern that already existed earlier looks brand new only if the evidence covering that earlier period was never checked.', 20, 2),
  ('mission-ai-sequence-to-sequence-12-o1-c1', 'solution', 'e2 and e3: the full log and its confirmed timestamps both show the recurring question was already present far earlier than the summary claims -- the pattern is not new, the summary is wrong about when it started.', 30, 3),
  ('mission-ai-sequence-to-sequence-12-o2-c1', 'orientation', 'The failure was not random -- it happened specifically on a long input, and specifically to early detail.', 10, 1),
  ('mission-ai-sequence-to-sequence-12-o2-c1', 'concept', 'A fixed-size vector has to represent the entire input at once, no matter how long that input is.', 20, 2),
  ('mission-ai-sequence-to-sequence-12-o2-c1', 'solution', 'b: the context bottleneck squeezed a long stretch of messages into one fixed-size vector, and detail from early in that stretch is exactly what tends to get lost first.', 30, 3),
  ('mission-ai-sequence-to-sequence-12-o3-c1', 'orientation', 'A correct fix should match the independently confirmed timestamps, not just tell a different story.', 10, 1),
  ('mission-ai-sequence-to-sequence-12-o3-c1', 'solution', 'e2: the attention-based re-run first-appearance claim matches the timestamps confirmed directly against the full log -- that is what recovering the correct timeline actually looks like, not just a different guess.', 20, 2),
  ('mission-ai-sequence-to-sequence-12-o4-c1', 'orientation', 'Think about what all three findings together say about trusting a single generated summary at face value.', 15, 1),
  ('mission-ai-sequence-to-sequence-12-o4-c1', 'solution', 'A generated summary is a claim, not a certainty -- especially one built without attention, it can silently drop real detail on long input, so any summary Cipher Division intends to act on needs to be checked against the underlying record, not just read.', 25, 2);
